def compile_and_run():
    # Compile the CUDA extension
    module = load_inline(
        name="batch_norm_cuda",
        cpp_sources=[],
        cuda_sources=[cuda_source],
        functions=["batch_norm_kernel_optimized"],
        extra_cuda_cflags=["-O3", "--use_fast_math", "-lcudart"],
        verbose=True
    )

    return module

# Create model class that uses our CUDA kernel
class ModelNew(torch.nn.Module):
    def __init__(self, num_features: int):
        super(ModelNew, self).__init__()
        self.num_features = num_features

        # Initialize parameters like BatchNorm2d
        self.weight = torch.nn.Parameter(torch.ones(num_features, dtype=torch.float16))
        self.bias = torch.nn.Parameter(torch.zeros(num_features, dtype=torch.float16))

        # Initialize running statistics
        self.register_buffer('running_mean', torch.zeros(num_features, dtype=torch.float16))
        self.register_buffer('running_var', torch.ones(num_features, dtype=torch.float16))

        # Set up training mode
        self.training = True

        # Compile CUDA kernel
        self.cuda_module = compile_and_run()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Ensure input is contiguous
        x = x.contiguous()

        # Get dimensions
        batch_size = x.shape[0]
        num_features = x.shape[1]
        spatial_size = x.shape[2] * x.shape[3]

        # Prepare data for kernel
        input_ptr = x.data_ptr()
        output = torch.empty_like(x, dtype=torch.float16)
        output_ptr = output.data_ptr()

        # Get parameter pointers
        weight_ptr = self.weight.data_ptr()
        bias_ptr = self.bias.data_ptr()
        running_mean_ptr = self.running_mean.data_ptr()
        running_var_ptr = self.running_var.data_ptr()

        # Kernel launch parameters
        threads_per_block = 256
        blocks_per_grid = (num_features + threads_per_block - 1) // threads_per_block

        # Launch kernel
        self.cuda_module.batch_norm_kernel_optimized[
            blocks_per_grid, threads_per_block
        ](
            input_ptr,
            output_ptr,
            weight_ptr,
            bias_ptr,
            running_mean_ptr,
            running_var_ptr,
            0.1,  # momentum (same as default BN)
            1e-5,  # eps (same as default BN)
            batch_size,
            num_features,
            spatial_size
        )

        return output

